            '⚠️ ' + m.bold('Merge conflicts detected') + ' — ' + conflicts.length +
                ' file(s) must be resolved before rework can be applied:\n' +
            conflicts.map(function (f) { return '* ' + m.code(f); }).join('\n'),
            'bgColor=#FFEBE6|borderColor=#DE350B') + '\n\n';
