function detectFailedChecks(scmOrOwner, repoOrHeadSha, headShaOrInputFolder, inputFolderOpt, jenkinsBasePathOpt) {
    var scm = null;
    var owner, repo, headSha, inputFolder, jenkinsBasePath;

