    if (!owner || !author) return false;
    if (author.toLowerCase() !== String(owner).toLowerCase()) return false;
    var branch = String((item && (item.branch || (item.pr && item.pr.branch))) || '');
    var title = String((item && (item.title || (item.pr && item.pr.title))) || '');
