    var prIdStr = String(prId);
    var sections = [];
    var rawThreads = [];

    try {
        var conversations = github_get_pr_conversations({
            workspace: workspace, repository: repository, pullRequestId: prIdStr
        });
        if (conversations && conversations.length > 0) {
            var reviewThreadByCommentId = {};
