        var body = String(t.body || '').split('\n')[0].trim();
        if (body.length > 120) body = body.substring(0, 117) + '...';
        return '* ' + m.inline(id) +
            (loc ? ' — ' + m.inline(loc) : '') +
            (body ? ' — "' + body + '"' : '') +
            ' — ' + reason;
