                    reviewThreads: {
                        nodes: realThreadsFixture().map(function(t) {
                            return {
                                id: t.graphqlId,
                                isResolved: false,
                                comments: { nodes: [{ databaseId: t.id }] }
                            };
                        })
                    }
                }
