                'input/PROJ-123/ci_failures.md': '# ⚠️ Failed CI Checks — Fix Before Completing Rework\n\nREAL FAILURE LOG',
                'input/PROJ-123/pr_discussions_raw.json': '{"threads": [{"threadId": "PRRT_real"}]}'
