        });
        scm.submitReview(42, 'REQUEST_CHANGES', 'Blocking issue in module X.');
        assert.equal(calls.length, 2);
        assert.equal(calls[0].tool, 'unapprove');
        assert.equal(calls[1].tool, 'comment');

